"use strict";
import { useState } from "react";
import { Flex, Text, styled as uiStyled } from "ui/src";
const ToggleContainer = uiStyled(Flex, {
  flexDirection: "row",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: 2,
  gap: 2
});
const ToggleButton = uiStyled(Flex, {
  paddingHorizontal: "$spacing12",
  paddingVertical: "$spacing4",
  borderRadius: "$roundedFull",
  cursor: "pointer",
  justifyContent: "center",
  alignItems: "center",
  variants: {
    active: {
      true: {
        backgroundColor: "$surface1"
      }
    }
  }
});
export default function OptionToggle({ options }) {
  const [selectedOption, setSelectedOption] = useState(options[0] || "");
  return <ToggleContainer>
      {options.map((option) => <ToggleButton key={option} active={option === selectedOption} onPress={() => setSelectedOption(option)}>
          <Text variant="buttonLabel4" color={option === selectedOption ? "$neutral1" : "$neutral2"}>
            {option}
          </Text>
        </ToggleButton>)}
    </ToggleContainer>;
}
