const getRandomInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const formatMoney = (amount) => "$" + amount.toLocaleString();
const vaultNames = [
  "Re7 WETH",
  "Steakhouse USDC",
  "Morpho Blue",
  "Gauntlet WETH",
  "Block Analitica",
  "Yearn V3",
  "Aave V3"
];
const curators = [
  "Re7 Labs",
  "Steakhouse Financial",
  "Morpho Association",
  "Gauntlet Network",
  "Block Analitica",
  "Yearn",
  "Aave"
];
const generateMockData = () => {
  const data = [];
  const count = getRandomInt(4, 10);
  data.push({
    id: "1",
    vaultName: "Re7 WETH",
    vaultIcon: getTokenLogoUrl("0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2") || "",
    // WETH
    hasAlert: true,
    curatorName: "Re7 Labs",
    curatorIcon: "",
    allocation: "$0",
    supplyShare: "0.00%",
    supplyShareColor: "#293249"
    // Grey/Empty
  });
  for (let i = 2; i <= count; i++) {
    const idx = getRandomInt(0, vaultNames.length - 1);
    const allocationVal = getRandomInt(0, 5e7);
    const shareVal = allocationVal / 1e8 * 100;
    const isLow = shareVal < 1;
    data.push({
      id: String(i),
      vaultName: vaultNames[idx] + (i > 1 ? ` ${i}` : ""),
      vaultIcon: getTokenLogoUrl("0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2") || "",
      hasAlert: Math.random() > 0.8,
      curatorName: curators[idx],
      curatorIcon: "",
      allocation: allocationVal === 0 ? "$0" : formatMoney(allocationVal),
      supplyShare: allocationVal === 0 ? "0.00%" : `${shareVal.toFixed(2)}%`,
      supplyShareColor: isLow ? "#293249" : "#4C82FB"
    });
  }
  return data;
};
const mockData = generateMockData();
export default function OverviewTable() {
  return <TableWrapper flexDirection="column">
      <Text variant="subheading1" color="$neutral1" marginBottom="$spacing16">
        Vaults Listing The Market
      </Text>
      <OverviewTableComponent data={mockData} loading={false} />
    </TableWrapper>;
}
